export function translate(locale: SiteLocale, source: string): string {
  if (locale === "fr") return source;
  const index = ({ en: 0, es: 1, pt: 2, zh: 3, ja: 4 } as const)[locale];
  return messages[source]?.[index] ?? source;
}
